import React,{useCallback,useEffect,useMemo,useState} from 'react';
import {Activity,ArrowDownToLine,ArrowRight,CheckCircle2,ChevronDown,ClipboardCheck,Clock3,FileText,Filter,GraduationCap,HeartHandshake,Home,LogOut,MapPin,Menu,Search,ShieldCheck,UploadCloud,Users,Wallet,AlertTriangle,BookOpen,Plus,X,Bell,RefreshCw,Sun,Moon} from 'lucide-react';
import {api,clearSession,getSavedUser,getToken,setSession} from './api';

const money=n=>new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:0}).format(n||0);
const dateFmt=d=>d?new Date(`${String(d).slice(0,10)}T00:00:00`).toLocaleDateString('en-KE',{day:'numeric',month:'short',year:'numeric'}):'—';
const statuses=['Submitted','Under Review','Verification','Additional Information Required','Committee Review','Approved','Rejected','Disbursed'];
const statusClass=s=>s==='Approved'||s==='Disbursed'?'success':s==='Rejected'?'danger':s?.startsWith('Additional')?'warning':'info';
function Badge({children,tone}){return <span className={`badge ${tone||statusClass(children)}`}>{children}</span>}
function Button({children,kind='primary',size='',className='',...props}){return <button className={`btn ${kind} ${size} ${className}`} {...props}>{children}</button>}
function Field({label,children,...props}){return <label className="field"><span>{label}</span>{children||<input {...props}/>}</label>}
function Notice({type='info',children,onClose}){return <div className={`notice ${type}`}>{type==='error'?<AlertTriangle size={18}/>:<CheckCircle2 size={18}/>}<span>{children}</span>{onClose&&<button className="icon-btn" onClick={onClose}><X size={16}/></button>}</div>}
function Empty({title,desc}){return <div className="empty"><div className="empty-icon"><FileText size={24}/></div><b>{title}</b><p>{desc}</p></div>}

export default function App(){
 const [user,setUser]=useState(getSavedUser()); const [page,setPage]=useState(getSavedUser()?.role==='admin'||getSavedUser()?.role==='reviewer'?'dashboard':'home');
 const [bursaries,setBursaries]=useState([]);const [applications,setApplications]=useState([]);const [stats,setStats]=useState(null);const [selected,setSelected]=useState(null);const [query,setQuery]=useState('');const [filter,setFilter]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [authMode,setAuthMode]=useState('login');const [mobileNav,setMobileNav]=useState(false);const [dark,setDark]=useState(false);const [notifications,setNotifications]=useState([]);
 const staff=user&&['admin','reviewer'].includes(user.role);
 const refresh=useCallback(async()=>{if(!getToken())return;try{const bs=await api('/bursaries');setBursaries(bs);const apps=await api('/applications');setApplications(apps);if(['admin','reviewer'].includes(getSavedUser()?.role)){setStats(await api('/dashboard/stats'));setNotifications(await api('/notifications'));}}catch(e){setError(e.message)}},[]);
 useEffect(()=>{if(getToken())refresh()},[refresh]);
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light'},[dark]);
 const run=async fn=>{setBusy(true);setError('');setNotice('');try{await fn()}catch(e){setError(e.message||'Something went wrong')}finally{setBusy(false)}};
 const logout=()=>{clearSession();setUser(null);setPage('home');setApplications([]);setBursaries([]);setSelected(null);setNotice('You have signed out.')};
 const navigate=p=>{setPage(p);setMobileNav(false);setError('');setNotice('');if(p==='dashboard'&&staff)refresh()};
 const navItems=staff?[['dashboard','Dashboard',Home],['applications','Applications',ClipboardCheck],['bursaries','Bursary programs',GraduationCap],['staff','Staff',Users],['reports','Reports',ArrowDownToLine]]:[['home','Home',Home],['profile','My Profile',Users],['bursaries','Bursaries',GraduationCap],['apply','Apply',Plus],['my-applications','My applications',ClipboardCheck]];
 const filtered=useMemo(()=>applications.filter(a=>(!filter||a.status===filter)&&(!query||[a.application_number,a.applicant_name,a.institution,a.student_number,a.bursary_name].join(' ').toLowerCase().includes(query.toLowerCase()))),[applications,filter,query]);
 async function authSubmit(e){e.preventDefault();const fd=new FormData(e.currentTarget);await run(async()=>{const payload=authMode==='login'?{email:fd.get('email'),password:fd.get('password')}:{full_name:fd.get('full_name'),email:fd.get('email'),phone:fd.get('phone'),password:fd.get('password')};const data=await api(`/auth/${authMode}`,{method:'POST',body:payload});setSession(data.access_token,data.user);setUser(data.user);setPage(['admin','reviewer'].includes(data.user.role)?'dashboard':'home');setNotice(`Welcome${data.user.full_name?`, ${data.user.full_name.split(' ')[0]}`:''}!`);});}
 async function createApplication(e){e.preventDefault();const form=e.currentTarget;if(!form)return;const fd=new FormData(form);const payload={bursary_id:Number(fd.get('bursary_id')),institution:fd.get('institution'),student_number:fd.get('student_number'),national_id:fd.get('national_id'),monthly_household_income:Number(fd.get('monthly_household_income')),household_size:Number(fd.get('household_size')),course:fd.get('course'),year_of_study:fd.get('year_of_study'),reason:fd.get('reason')};await run(async()=>{const a=await api('/applications',{method:'POST',body:payload});const fileInputs=e.currentTarget.querySelectorAll('input[type="file"]');for(const input of fileInputs){const file=input.files?.[0];const docType=input.dataset.docType;if(file&&docType){try{const docFd=new FormData();docFd.append('document_type',docType);docFd.append('file',file);await api(`/applications/${a.application_number}/documents`,{method:'POST',body:docFd})}catch(err){console.error(`Failed to upload ${docType}:`,err)}}}await refresh();const updated=await api(`/applications/${a.application_number}`);setApplications(prev=>[updated,...prev.filter(x=>x.id!==updated.id)]);setSelected(updated);setPage('my-applications');setNotice(`Application submitted. Your reference is ${a.application_number}.`);});}
 async function changeStatus(a,status,comment=''){await run(async()=>{await api(`/applications/${a.application_number}/status`,{method:'PATCH',body:{status,reviewer_comment:comment}});await refresh();const updated=await api(`/applications/${a.application_number}`);setSelected(updated);setNotice(`${a.application_number} updated to ${status}.`);});}
 async function uploadDoc(e,a,docType){const file=e.target.files?.[0];if(!file)return;await run(async()=>{const fd=new FormData();fd.append('document_type',docType);fd.append('file',file);await api(`/applications/${a.application_number}/documents`,{method:'POST',body:fd});await refresh();const updated=await api(`/applications/${a.application_number}`);setSelected(updated);setNotice(`${file.name} uploaded.`);});e.target.value='';}
 async function downloadReport(){await run(async()=>{const blob=await api('/reports/applications.csv');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='smartbursary-applications.csv';a.click();URL.revokeObjectURL(url);});}
 if(!user){return <div className="auth-shell"><div className="auth-side"><Brand/><div className="auth-message"><div className="eyebrow">EDUCATION OPPORTUNITY, MADE CLEAR</div><h1>Make your next step <em>possible.</em></h1><p>One place to find bursaries, submit your documents and follow your application from submission to decision.</p><div className="auth-points"><span><ShieldCheck/> Secure application workflow</span><span><Activity/> Transparent status tracking</span><span><HeartHandshake/> Human-led award decisions</span></div></div><div className="auth-foot">SmartBursary · Education financial assistance</div></div><div className="auth-main"><form className="auth-card" onSubmit={authSubmit}><div className="mobile-brand"><Brand/></div><div className="eyebrow">WELCOME TO SMARTBURSARY</div><h2>{authMode==='login'?'Good to see you again':'Create your account'}</h2><p className="muted">{authMode==='login'?'Sign in to continue to your bursary workspace.':'Start your application journey in a few simple steps.'}</p>{error&&<Notice type="error">{error}</Notice>}{notice&&<Notice>{notice}</Notice>}{authMode==='register'&&<Field label="Full name"><input name="full_name" required minLength="2" placeholder="e.g. Andrew Wekesa" autoComplete="name"/></Field>}<Field label="Email address"><input name="email" type="email" required placeholder="you@example.com" autoComplete="email"/></Field>{authMode==='register'&&<Field label="Phone number (optional)"><input name="phone" type="tel" placeholder="07xx xxx xxx"/></Field>}<Field label="Password"><input name="password" type="password" required minLength="8" placeholder={authMode==='register'?'At least 8 characters':'Enter your password'} autoComplete={authMode==='login'?'current-password':'new-password'}/></Field><Button disabled={busy} type="submit" className="auth-submit">{busy?'Please wait…':authMode==='login'?'Sign in':'Create account'} <ArrowRight size={18}/></Button><p className="auth-switch">{authMode==='login'?"Don't have an account?":"Already registered?"} <button type="button" onClick={()=>{setAuthMode(authMode==='login'?'register':'login');setError('')}}>{authMode==='login'?'Create an account':'Sign in'}</button></p><div className="auth-demo"><ShieldCheck size={16}/><span>Staff accounts are provisioned by the system administrator. Do not use real personal data in a demo environment.</span></div></form></div></div>}
 return <div className="app-shell"><aside className={`sidebar ${mobileNav?'open':''}`}><Brand/><div className="workspace-label">WORKSPACE</div><nav className="side-nav">{navItems.map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>navigate(id)}><Icon size={18}/><span>{label}</span>{id==='my-applications'&&applications.length>0&&<small>{applications.length}</small>}</button>)}</nav><div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><HeartHandshake size={18}/></div><b>Need a hand?</b><p>Keep your reference number close when asking about an application.</p></div><button className="side-user" onClick={logout}><div className="avatar">{user.full_name?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><span><b>{user.full_name}</b><small>{user.role==='admin'?'Administrator':user.role==='reviewer'?'Reviewer':'Applicant'}</small></span><LogOut size={17}/></button></div></aside><div className="main-column"><header className="topbar"><button className="mobile-menu icon-btn" onClick={()=>setMobileNav(!mobileNav)}><Menu/></button><div className="crumb"><span>SmartBursary</span><span>/</span><b>{navItems.find(n=>n[0]===page)?.[1]||({detail:'Application details',track:'Track application'}[page])||'Workspace'}</b></div><div className="top-actions"><button className="icon-btn" aria-label="Toggle theme" onClick={()=>setDark(!dark)}>{dark?<Sun size={18}/>:<Moon size={18}/>}</button><div className="top-avatar">{user.full_name?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div></div></header><main className="content">{error&&<Notice type="error" onClose={()=>setError('')}>{error}</Notice>}{notice&&<Notice onClose={()=>setNotice('')}>{notice}</Notice>}
 {page==='home'&&<HomePage user={user} bursaries={bursaries} applications={applications} go={navigate}/>}
 {page==='profile'&&!staff&&<ProfilePage user={user} busy={busy} run={run} refresh={refresh} setNotice={setNotice}/>}
 {page==='bursaries'&&<BursariesPage bursaries={bursaries} staff={staff} go={navigate} busy={busy} run={run} refresh={refresh}/>}
 {page==='staff'&&staff&&user.role==='admin'&&<StaffPage run={run} refresh={refresh} busy={busy}/>}
 {page==='apply'&&<ApplyPage bursaries={bursaries} submit={createApplication} busy={busy}/>}
 {page==='my-applications'&&<ApplicationsPage items={applications} staff={false} go={navigate} onSelect={a=>{setSelected(a);setPage('detail')}}/>}
 {page==='dashboard'&&staff&&<Dashboard stats={stats} applications={applications} go={navigate} onSelect={a=>{setSelected(a);setPage('detail')}} refresh={refresh}/>}
 {page==='applications'&&staff&&<ApplicationsPage items={filtered} staff query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} go={navigate} onSelect={a=>{setSelected(a);setPage('detail')}}/>}
 {page==='detail'&&selected&&<DetailPage item={selected} staff={staff} onStatus={changeStatus} onUpload={uploadDoc} busy={busy} go={navigate}/>}
 {page==='reports'&&staff&&<ReportsPage applications={applications} download={downloadReport} busy={busy}/>}
 {page==='track'&&<TrackPage applications={applications} onFind={async no=>{await run(async()=>{const a=await api(`/applications/${encodeURIComponent(no)}`);setSelected(a);setPage('detail')})}}/>}
 </main><footer className="footer"><span>© {new Date().getFullYear()} SmartBursary</span><span>AI-assisted indicators support review; <b>people make award decisions.</b></span></footer></div>{mobileNav&&<button className="nav-backdrop" onClick={()=>setMobileNav(false)} aria-label="Close navigation"/>}</div>
}
function Brand(){return <div className="brand"><span className="brand-mark"><span/></span><span>SmartBursary</span></div>}
function PageHeading({eyebrow,title,desc,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{desc&&<p>{desc}</p>}</div>{action&&<div>{action}</div>}</div>}
function HomePage({user,bursaries,applications,go}){const active=applications.filter(a=>!['Approved','Rejected','Disbursed'].includes(a.status));const recent=applications.slice(0,3);return <><div className="welcome-banner"><div className="welcome-copy"><div className="eyebrow light">YOUR EDUCATION JOURNEY</div><h1>Hello, {user.full_name?.split(' ')[0]} <span>👋</span></h1><p>Your next opportunity starts with a clear plan. Explore funding, prepare your documents and keep your progress in view.</p><div className="welcome-actions"><Button onClick={()=>go('apply')}>Start an application <ArrowRight size={17}/></Button><button className="text-btn light-text" onClick={()=>go('bursaries')}>Explore bursaries</button></div></div><div className="banner-art"><div className="art-circle"><GraduationCap size={84}/></div><div className="art-tag"><CheckCircle2 size={16}/> Your future, in progress</div></div></div><div className="section-head"><div><div className="eyebrow">AT A GLANCE</div><h2>Your workspace</h2></div><button className="text-btn" onClick={()=>go('my-applications')}>View all applications <ArrowRight size={16}/></button></div><div className="stat-grid applicant-stats"><Stat icon={ClipboardCheck} label="Applications submitted" value={applications.length} tone="green"/><Stat icon={Clock3} label="In progress" value={active.length} tone="amber"/><Stat icon={CheckCircle2} label="Approved" value={applications.filter(a=>a.status==='Approved'||a.status==='Disbursed').length} tone="blue"/><Stat icon={GraduationCap} label="Open programs" value={bursaries.length} tone="purple"/></div><div className="two-col home-lower"><section className="panel"><div className="panel-head"><div><h3>Recent applications</h3><p>Your latest bursary activity</p></div><button className="text-btn" onClick={()=>go('my-applications')}>See all</button></div>{recent.length?recent.map(a=><button className="application-row" key={a.id} onClick={()=>go('my-applications')}><div className="program-icon"><FileText size={19}/></div><div className="application-row-main"><b>{a.bursary_name}</b><small>{a.application_number} · {dateFmt(a.submitted_at)}</small></div><Badge>{a.status}</Badge><ArrowRight size={16} className="row-arrow"/></button>):<Empty title="Your journey starts here" desc="Once you submit an application, its progress will appear here."/>}</section><section className="panel opportunity-panel"><div className="opportunity-illustration"><Wallet size={32}/></div><div className="eyebrow">FIND YOUR FIT</div><h3>Funding for your next chapter</h3><p>Browse current bursary programs, review the eligibility criteria and note the documents you will need.</p><Button kind="outline" onClick={()=>go('bursaries')}>Browse programs <ArrowRight size={16}/></Button></section></div></>}
function Stat({icon:Icon,label,value,tone}){return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={20}/></div><div><div className="stat-value">{value??'—'}</div><div className="stat-label">{label}</div></div></div>}
function BursariesPage({bursaries,staff,go,busy,run,refresh}){const [search,setSearch]=useState('');const [selectedConstituency,setSelectedConstituency]=useState('');const [constituencies,setConstituencies]=useState([]);const [showCreate,setShowCreate]=useState(false);const [createBusy,setCreateBusy]=useState(false);const user=getSavedUser();useEffect(()=>{loadConstituencies()},[]);const loadConstituencies=async()=>{try{const data=await api('/bursaries/constituencies');setConstituencies(data)}catch(e){console.error(e)}};const list=bursaries.filter(b=>{const searchMatch=!search||(b.name+' '+b.description+' '+b.eligibility+' '+(b.constituency||'')).toLowerCase().includes(search.toLowerCase());const constituencyMatch=!selectedConstituency||b.constituency===selectedConstituency;return searchMatch&&constituencyMatch});async function create(e){e.preventDefault();const fd=new FormData(e.currentTarget);setCreateBusy(true);try{await api('/bursaries',{method:'POST',body:{name:fd.get('name'),description:fd.get('description'),eligibility:fd.get('eligibility'),constituency:fd.get('constituency'),amount_kes:Number(fd.get('amount_kes')),deadline:fd.get('deadline'),required_documents:String(fd.get('required_documents')).split('\n').map(s=>s.trim()).filter(Boolean),active:true}});setShowCreate(false);await refresh();await loadConstituencies()}catch(e){alert(e.message)}finally{setCreateBusy(false)}}async function toggleActive(id){await run(async()=>{await api(`/bursaries/${id}/toggle`,{method:'PATCH'});await refresh()})}return <><PageHeading eyebrow="FUNDING DIRECTORY" title={staff?'Bursary programs':'Open bursaries'} desc={staff?'Manage funding opportunities and their requirements.':'Browse all available opportunities. You can apply only to bursaries in your home constituency.'} action={staff&&<Button onClick={()=>setShowCreate(!showCreate)}><Plus size={17}/> Add program</Button>}/><div className="bursary-filters"><div className="searchbox"><Search size={18}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search bursaries, eligibility or constituency…"/></div>{constituencies.length>0&&<div className="selectbox constituency-select"><MapPin size={17}/><select value={selectedConstituency} onChange={e=>setSelectedConstituency(e.target.value)}><option value="">All Constituencies</option>{constituencies.map(c=><option key={c.constituency} value={c.constituency}>{c.constituency} ({c.count})</option>)}</select></div>}{selectedConstituency&&<button className="clear-filter" onClick={()=>setSelectedConstituency('')}><X size={14}/> Clear</button>}</div>{showCreate&&<form className="panel create-form" onSubmit={create}><h3>New bursary program</h3><div className="form-grid"><Field label="Program name"><input name="name" required/></Field><Field label="Constituency"><input name="constituency" placeholder="e.g. Webuye East" required/></Field><Field label="Funding amount (KES)"><input name="amount_kes" type="number" min="0" required/></Field><Field label="Application deadline"><input name="deadline" type="date" required/></Field><Field label="Eligibility criteria"><input name="eligibility" required/></Field><Field label="Description"><textarea name="description" rows="2"/></Field><Field label="Required documents (one per line)"><textarea name="required_documents" rows="3" required/></Field></div><div className="form-actions"><Button type="submit" disabled={createBusy}>{createBusy?'Saving…':'Save program'}</Button><Button kind="ghost" type="button" onClick={()=>setShowCreate(false)}>Cancel</Button></div></form>}{list.length===0?<Empty title="No programs found" desc={selectedConstituency?`No bursaries found for ${selectedConstituency}. Try another constituency or clear filter.`:"Try another search or check back later."}/>:<div className="program-grid">{list.map((b,i)=>{const isEligible=staff||!user.constituency||!b.constituency||user.constituency===b.constituency;return <article className={`program-card ${!isEligible?'ineligible':''}`} key={b.id}><div className="program-card-top"><div className={`program-icon big hue-${i%4}`}><GraduationCap size={23}/></div><Badge tone={b.active?(new Date(`${b.deadline}T23:59:59`)<new Date()?'danger':'success'):'danger'}>{b.active?(new Date(`${b.deadline}T23:59:59`)<new Date()?'Deadline passed':'Open'):'Closed'}</Badge></div>{b.constituency&&<div className={`constituency-badge ${isEligible?'eligible':'ineligible'}`}><MapPin size={12}/> {b.constituency}{!staff&&user.constituency&&user.constituency!==b.constituency&&<small> (Not your constituency)</small>}</div>}<h3>{b.name}</h3><p className="program-desc">{b.description||b.eligibility}</p><div className="funding-amount">{money(b.amount_kes)} <small>potential award</small></div><div className="program-meta"><span><Clock3 size={15}/> Deadline</span><b>{dateFmt(b.deadline)}</b></div><div className="eligibility"><b>Eligibility</b><p>{b.eligibility}</p></div><div className="doc-tags"><b>Documents to prepare</b><div>{b.required_documents.map(d=><span key={d}>{d}</span>)}</div></div>{staff?<Button block onClick={()=>toggleActive(b.id)} kind={b.active?'outline':'primary'}>{b.active?'Close applications':'Open applications'}</Button>:isEligible?<Button block onClick={()=>go('apply')}>Apply for this program <ArrowRight size={16}/></Button>:<Button block disabled title={`Only residents of ${b.constituency} can apply`}>Not eligible to apply</Button>}</article>})}</div>}</>}
function ApplyPage({bursaries,submit,busy}){const [program,setProgram]=useState('');const [documents,setDocuments]=useState({});const [profile,setProfile]=useState(null);const user=getSavedUser();const eligibleBursaries=bursaries.filter(b=>!user.constituency||!b.constituency||user.constituency===b.constituency);useEffect(()=>{if(eligibleBursaries.length&&!program)setProgram(String(eligibleBursaries[0].id));loadProfile()},[eligibleBursaries,program]);const loadProfile=async()=>{try{const data=await api('/profile');setProfile(data)}catch(e){console.error(e)}};const chosen=eligibleBursaries.find(b=>String(b.id)===program);const handleFileChange=(docType,file)=>{setDocuments(prev=>({...prev,[docType]:file}))};const handleSubmit=async(e)=>{e.preventDefault();await submit(e);};if(profile&&!profile.profile_complete){return <div className="panel" style={{maxWidth:'620px',margin:'0 auto',padding:'32px',textAlign:'center'}}><div className="empty-icon" style={{margin:'0 auto 18px'}}><AlertTriangle size={28} color="var(--yellow)"/></div><h2>Profile Incomplete</h2><p style={{fontSize:'.92rem',color:'var(--mute)',marginBottom:'22px'}}>You must complete your profile before applying for bursaries. This includes filling all required fields and uploading necessary documents.</p><Button onClick={()=>window.location.hash='#/profile'}>Complete Your Profile <ArrowRight size={17}/></Button></div>}if(eligibleBursaries.length===0){return <div className="panel" style={{maxWidth:'620px',margin:'0 auto',padding:'32px',textAlign:'center'}}><div className="empty-icon" style={{margin:'0 auto 18px'}}><MapPin size={28} color="var(--green)"/></div><h2>No Eligible Bursaries</h2><p style={{fontSize:'.92rem',color:'var(--mute)',marginBottom:'22px'}}>There are currently no open bursaries for your constituency ({user.constituency}). Check back later for new opportunities, or browse all bursaries to stay informed.</p><div style={{display:'flex',gap:'12px',justifyContent:'center'}}><Button onClick={()=>window.location.hash='#/bursaries'}>Browse All Bursaries</Button><Button kind="outline" onClick={()=>window.location.hash='#/home'}>Go Home</Button></div></div>}return <><PageHeading eyebrow="APPLICATION FORM" title="Start your application" desc="Complete each section carefully. Required fields are marked by the browser."/><div className="form-layout"><form className="panel application-form" onSubmit={handleSubmit}><div className="form-section-title"><span>01</span><div><h3>Personal and academic details</h3><p>Tell us how we can identify your application.</p></div></div><div className="form-grid"><Field label="Institution"><input name="institution" required placeholder="University, college or school"/></Field><Field label="Student number"><input name="student_number" required placeholder="Your student registration number"/></Field><Field label="National ID / birth certificate number"><input name="national_id" placeholder="Enter if applicable"/></Field><Field label="Course or program"><input name="course" placeholder="e.g. Software Engineering"/></Field><Field label="Year of study"><select name="year_of_study" defaultValue=""><option value="">Select year</option>{['Year 1','Year 2','Year 3','Year 4','Year 5','Secondary school','TVET'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Monthly household income (KES)"><input name="monthly_household_income" type="number" min="0" required placeholder="0"/></Field><Field label="People in household"><input name="household_size" type="number" min="1" max="50" defaultValue="1" required/></Field></div><div className="form-section-title gap-top"><span>02</span><div><h3>Choose a bursary</h3><p>Check eligibility and deadline before continuing.</p></div></div><Field label="Bursary program"><select name="bursary_id" value={program} onChange={e=>setProgram(e.target.value)} required>{eligibleBursaries.map(b=><option value={String(b.id)} key={b.id}>{b.name} — {money(b.amount_kes)}</option>)}</select></Field>{chosen&&<div className="selected-program"><div><GraduationCap size={21}/></div><section><b>{chosen.name}</b><p>{chosen.eligibility}</p><small>Deadline: {dateFmt(chosen.deadline)} · Amount: {money(chosen.amount_kes)}{chosen.constituency&&<> · <MapPin size={11} style={{display:'inline',verticalAlign:'middle'}}/> {chosen.constituency}</>}</small></section></div>}<div className="form-section-title gap-top"><span>03</span><div><h3>Why do you need this support?</h3><p>Share the circumstances relevant to your application.</p></div></div><Field label="Reason for applying"><textarea name="reason" rows="5" placeholder="Explain your financial need, education goals and any relevant circumstances…"/></Field><div className="form-section-title gap-top"><span>04</span><div><h3>Upload supporting documents</h3><p>Attach all required documents below. You can also add more documents after submission.</p></div></div>{chosen&&chosen.required_documents.length>0?<div className="document-upload-section">{chosen.required_documents.map(docType=><div className="upload-field" key={docType}><Field label={docType}><label className="file-input-label"><input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e=>handleFileChange(docType,e.target.files[0])} data-doc-type={docType}/>{documents[docType]?<span className="file-selected"><FileText size={16}/> {documents[docType].name} ({(documents[docType].size/1024).toFixed(0)} KB)</span>:<span className="file-placeholder"><UploadCloud size={16}/> Choose file (PDF, JPG, PNG · Max 5 MB)</span>}</label></Field></div>)}</div>:<div className="notice info"><FileText size={18}/><span>No specific documents required for this program. You can upload documents after submission if needed.</span></div>}<div className="privacy-note"><ShieldCheck size={18}/><span>Your information is intended for authorized bursary processing. Do not submit false or misleading details.</span></div><div className="form-actions"><Button type="submit" disabled={busy||!eligibleBursaries.length}>{busy?'Submitting…':'Submit application'} <ArrowRight size={17}/></Button></div></form><aside className="panel form-aside"><div className="aside-icon"><ClipboardCheck size={23}/></div><h3>Before you submit</h3><ul className="check-list"><li><CheckCircle2/> Check the eligibility criteria.</li><li><CheckCircle2/> Confirm your student details are correct.</li><li><CheckCircle2/> Prepare the required documents.</li><li><CheckCircle2/> Keep your application reference number.</li></ul><div className="note-box"><b>How decisions work</b><p>Automated indicators can help reviewers prioritize checks. Only an authorized human decision-maker can approve or reject an award.</p></div></aside></div></>}
function ApplicationsPage({items,staff,query,setQuery,filter,setFilter,go,onSelect}){return <><PageHeading eyebrow={staff?'REVIEW WORKSPACE':'YOUR RECORDS'} title={staff?'Applications':'My applications'} desc={staff?'Search, filter and open an application to review documents and update its status.':'View each reference number and follow the progress of your applications.'} action={!staff&&<Button onClick={()=>go('apply')}><Plus size={17}/> New application</Button>}/>{staff&&<div className="toolbar"><div className="searchbox"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search name, reference, institution…"/></div><div className="selectbox"><Filter size={17}/><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All statuses</option>{statuses.map(s=><option key={s}>{s}</option>)}</select></div></div>}<div className="panel table-panel">{items.length===0?<Empty title="No applications yet" desc={staff?'No applications match your current filters.':'Your submitted applications will appear here.'}/>:<div className="table-wrap"><table><thead><tr>{staff&&<th>Applicant</th>}<th>Reference</th><th>Program</th><th>Institution</th><th>Submitted</th>{staff&&<th>Priority</th>}<th>Status</th><th></th></tr></thead><tbody>{items.map(a=><tr key={a.id} onClick={()=>onSelect(a)} tabIndex="0" onKeyDown={e=>e.key==='Enter'&&onSelect(a)}>{staff&&<td><b>{a.applicant_name}</b><small>{a.applicant_email}</small></td>}<td><b className="ref-number">{a.application_number}</b><small>{a.student_number}</small></td><td>{a.bursary_name}<small>{money(a.amount_kes)}</small></td><td>{a.institution}</td><td>{dateFmt(a.submitted_at)}</td>{staff&&<td><span className="priority-number">{a.priority_score}%</span><div className="meter"><i style={{width:`${a.priority_score}%`}}/></div></td>}<td><Badge>{a.status}</Badge></td><td><button className="icon-btn" aria-label="Open application" onClick={e=>{e.stopPropagation();onSelect(a)}}><ArrowRight size={17}/></button></td></tr>)}</tbody></table></div>}</div></>}
function Dashboard({stats,applications,go,onSelect,refresh}){const high=applications.filter(a=>a.duplicate_risk==='HIGH');const user=getSavedUser();return <><PageHeading eyebrow="OVERVIEW" title={`Good day, ${user.role==='reviewer'?'reviewer':'administrator'}`} desc="Here is a snapshot of bursary activity and the applications that need attention." action={<Button kind="outline" onClick={refresh}><RefreshCw size={16}/> Refresh</Button>}/>{user.role==='reviewer'&&user.constituency&&<div className="constituency-banner"><MapPin size={18}/><div><b>Your Constituency:</b> {user.constituency}</div></div>}<div className="stat-grid dashboard-stats"><Stat icon={ClipboardCheck} label="Total applications" value={stats?.total??applications.length} tone="green"/><Stat icon={Clock3} label="Pending review" value={stats?.pending??'—'} tone="amber"/><Stat icon={CheckCircle2} label="Approved" value={stats?.statuses?.Approved??'—'} tone="blue"/><Stat icon={AlertTriangle} label="Duplicate flags" value={stats?.duplicate_flags??high.length} tone="red"/></div><div className="dashboard-grid"><section className="panel"><div className="panel-head"><div><h3>Applications to review</h3><p>Highest priority scores first; flags require human verification.</p></div><button className="text-btn" onClick={()=>go('applications')}>All applications <ArrowRight size={16}/></button></div>{applications.length?applications.slice().sort((a,b)=>b.priority_score-a.priority_score).slice(0,5).map(a=><button className="review-row" key={a.id} onClick={()=>onSelect(a)}><div className="avatar small-avatar">{a.applicant_name?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><div className="review-main"><b>{a.applicant_name}</b><small>{a.application_number} · {a.bursary_name}</small></div><div className="review-score"><b>{a.priority_score}%</b><small>support score</small></div><Badge>{a.status}</Badge><ArrowRight size={16}/></button>):<Empty title="No applications to review" desc="New applications will show up here."/>}</section><section className="panel"><div className="panel-head"><div><h3>Status overview</h3><p>Application pipeline</p></div></div><div className="status-bars">{['Submitted','Under Review','Verification','Committee Review','Approved','Rejected','Disbursed'].map(s=>{const n=stats?.statuses?.[s]??applications.filter(a=>a.status===s).length;const total=Math.max(1,stats?.total??applications.length);return <div className="status-bar-row" key={s}><div><span>{s}</span><b>{n}</b></div><div className="bar-track"><i style={{width:`${Math.min(100,n/total*100)}%`}}/></div></div>})}</div><div className="note-box compact"><b>Decision support only</b><p>Priority scores and duplicate indicators are prompts for review, not automated funding decisions.</p></div></section></div>{high.length>0&&<section className="panel flagged-panel"><div className="flag-heading"><AlertTriangle size={20}/><div><h3>Possible duplicate applications</h3><p>Check the underlying records before taking action.</p></div></div>{high.slice(0,3).map(a=><button className="flag-row" key={a.id} onClick={()=>onSelect(a)}><span>{a.applicant_name} · {a.student_number}</span><Badge tone="danger">High risk</Badge><ArrowRight size={16}/></button>)}</section>}</>}
function DetailPage({item:a,staff,onStatus,onUpload,busy,go}){const [comment,setComment]=useState(a.reviewer_comment||'');const [newStatus,setNewStatus]=useState(a.status);const [uploadType,setUploadType]=useState('');const [showStatus,setShowStatus]=useState(false);const steps=['Submitted','Under Review','Verification','Committee Review','Approved','Disbursed'];const activeIndex=steps.indexOf(a.status);return <><button className="back-link" onClick={()=>go(staff?'applications':'my-applications')}>← Back to {staff?'applications':'my applications'}</button><PageHeading eyebrow="APPLICATION DETAILS" title={a.application_number} desc={`${a.bursary_name} · Submitted ${dateFmt(a.submitted_at)}`} action={<Badge>{a.status}</Badge>}/><div className="detail-grid"><div className="detail-main"><section className="panel"><div className="panel-head"><div><h3>Application progress</h3><p>Current stage in the review process</p></div></div><div className="progress-steps">{steps.map((s,i)=><div className={`progress-step ${i<activeIndex?'done':i===activeIndex?'current':''}`} key={s}><span>{i<activeIndex?<CheckCircle2 size={17}/>:i+1}</span><small>{s}</small></div>)}</div>{a.status==='Additional Information Required'&&<Notice type="error">The reviewer needs additional information. Check the document requirements below.</Notice>}{a.status==='Rejected'&&<Notice type="error">This application was not approved. Contact the bursary office if you need clarification.</Notice>}</section><section className="panel"><div className="panel-head"><div><h3>Applicant information</h3><p>Information submitted for review</p></div></div><div className="info-grid"><Info label="Full name" value={a.applicant_name}/><Info label="Email address" value={a.applicant_email}/><Info label="Institution" value={a.institution}/><Info label="Student number" value={a.student_number}/><Info label="National ID" value={a.national_id||'Not provided'}/><Info label="Course" value={a.course||'Not provided'}/><Info label="Year of study" value={a.year_of_study||'Not provided'}/><Info label="Household size" value={`${a.household_size} people`}/><Info label="Monthly household income" value={money(a.monthly_household_income)}/><Info label="Bursary amount" value={money(a.amount_kes)}/></div><div className="reason-box"><b>Reason for applying</b><p>{a.reason||'No explanation provided.'}</p></div></section><section className="panel"><div className="panel-head"><div><h3>Supporting documents</h3><p>Files attached to this application</p></div></div>{a.documents?.length?a.documents.map(d=><div className="document-row" key={d.id}><div className="doc-icon"><FileText size={20}/></div><div className="document-info"><b>{d.document_type}</b><small>{d.original_filename} · {(d.size_bytes/1024).toFixed(0)} KB</small></div><Badge tone={d.verification_status==='Verified'?'success':d.verification_status==='Rejected'?'danger':'warning'}>{d.verification_status}</Badge><button className="icon-btn" title="Download document" onClick={async()=>{try{const blob=await api(`/documents/${d.id}/download`);const url=URL.createObjectURL(blob);const el=document.createElement('a');el.href=url;el.download=d.original_filename;el.click();URL.revokeObjectURL(url)}catch(e){alert(e.message)}}}><ArrowDownToLine size={17}/></button>{staff&&<select className="verify-select" value={d.verification_status} onChange={e=>runVerify(d.id,e.target.value)}><option>Pending</option><option>Verified</option><option>Rejected</option><option>More information required</option></select>}</div>):<Empty title="No documents uploaded" desc="Upload each document requested by the bursary program."/>}{!staff&&<div className="upload-inline"><Field label="Document type"><input value={uploadType} onChange={e=>setUploadType(e.target.value)} placeholder="e.g. Fee structure"/></Field><label className="upload-button"><UploadCloud size={17}/> Choose file<input type="file" accept=".pdf,.jpg,.jpeg,.png" disabled={busy||!uploadType.trim()} onChange={e=>onUpload(e,a,uploadType)}/></label><small>PDF, JPG or PNG · Max 5 MB</small></div>}</section></div><aside className="detail-aside"><section className="panel"><div className="panel-head"><div><h3>Review indicators</h3><p>Automated assistance, not a verdict</p></div></div><div className="indicator"><div><span>Financial need</span><Badge tone={a.financial_need==='HIGH'?'warning':'info'}>{a.financial_need}</Badge></div><p>Based on reported household income.</p></div><div className="indicator"><div><span>Education need</span><Badge>{a.education_need}</Badge></div><p>Requires context from the bursary criteria and reviewer.</p></div><div className="indicator"><div><span>Duplicate risk</span><Badge tone={a.duplicate_risk==='HIGH'?'danger':'success'}>{a.duplicate_risk}</Badge></div><p>{a.duplicate_risk==='HIGH'?'Potential match found. Confirm records manually.':'No matching student number or ID found in the current dataset.'}</p></div><div className="score-card"><span>Support priority score</span><b>{a.priority_score}%</b><div className="meter wide"><i style={{width:`${a.priority_score}%`}}/></div><small>Use only to help organize human review.</small></div></section>{staff&&<section className="panel decision-panel"><h3>Record review decision</h3><p>Decisions are recorded with an audit entry and applicant notification.</p><Field label="Application status"><select value={newStatus} onChange={e=>setNewStatus(e.target.value)}>{statuses.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Reviewer comment"><textarea rows="4" value={comment} onChange={e=>setComment(e.target.value)} placeholder="Record findings or next steps…"/></Field><Button block disabled={busy} onClick={()=>onStatus(a,newStatus,comment)}>{busy?'Saving…':'Save review update'}</Button></section>}<section className="panel"><h3>Review history</h3><div className="history-item"><span className="history-dot"/><div><b>Application submitted</b><small>{new Date(a.submitted_at).toLocaleString()}</small></div></div><div className="history-item"><span className="history-dot muted-dot"/><div><b>Last updated</b><small>{new Date(a.updated_at).toLocaleString()}</small></div></div>{a.reviewer_comment&&<div className="reason-box"><b>Latest reviewer comment</b><p>{a.reviewer_comment}</p></div>}</section></aside></div></>;async function runVerify(id,status){try{await api(`/documents/${id}/verification?status=${encodeURIComponent(status)}`,{method:'PATCH'});a.documents=a.documents.map(d=>d.id===id?{...d,verification_status:status}:d);go('detail')}catch(e){alert(e.message)}}}
function Info({label,value}){return <div className="info-item"><small>{label}</small><b>{value||'—'}</b></div>}
function ReportsPage({applications,download,busy}){const approved=applications.filter(a=>['Approved','Disbursed'].includes(a.status));const pending=applications.filter(a=>!['Approved','Rejected','Disbursed'].includes(a.status));const totalAmount=approved.reduce((sum,a)=>sum+(a.amount_kes||0),0);return <><PageHeading eyebrow="REPORTING & EXPORTS" title="Reports" desc="Review current application statistics and export a CSV for further analysis." action={<Button onClick={download} disabled={busy}><ArrowDownToLine size={17}/> Export CSV</Button>}/><div className="stat-grid"><Stat icon={ClipboardCheck} label="Applications" value={applications.length} tone="green"/><Stat icon={Clock3} label="Pending" value={pending.length} tone="amber"/><Stat icon={CheckCircle2} label="Approved / disbursed" value={approved.length} tone="blue"/><Stat icon={Wallet} label="Potential approved allocation" value={money(totalAmount)} tone="purple"/></div><section className="panel"><div className="panel-head"><div><h3>Application summary</h3><p>Current snapshot from the system database.</p></div></div><div className="report-list">{statuses.map(s=>{const n=applications.filter(a=>a.status===s).length;return <div className="report-row" key={s}><div><Badge>{s}</Badge><span>{n} application{n===1?'':'s'}</span></div><div className="report-track"><i style={{width:`${applications.length?n/applications.length*100:0}%`}}/></div><b>{applications.length?Math.round(n/applications.length*100):0}%</b></div>})}</div><div className="note-box"><b>Reporting note</b><p>Exported reports contain applicant personal information. Store and share them only with authorized people.</p></div></section></>}
function TrackPage({applications,onFind}){const [number,setNumber]=useState('');return <><PageHeading eyebrow="APPLICATION TRACKING" title="Track an application" desc="Enter the reference number shown when you submitted your application."/><form className="panel track-form" onSubmit={e=>{e.preventDefault();onFind(number.trim())}}><div className="track-icon"><Search size={24}/></div><Field label="Application reference number"><input value={number} onChange={e=>setNumber(e.target.value)} placeholder="e.g. SB-2026-00001" required/></Field><Button type="submit">Find application <ArrowRight size={17}/></Button><p className="muted small-text">You must be signed in with the account that owns the application.</p></form>{applications.length>0&&<div className="panel"><h3>Your recent references</h3>{applications.slice(0,5).map(a=><button className="application-row" key={a.id} onClick={()=>onFind(a.application_number)}><div className="application-row-main"><b>{a.application_number}</b><small>{a.bursary_name}</small></div><Badge>{a.status}</Badge><ArrowRight size={16}/></button>)}</div>}</>}

function ProfilePage({user,busy,run,refresh,setNotice}){const [profile,setProfile]=useState(null);const [editMode,setEditMode]=useState(false);const [formData,setFormData]=useState({});const [uploadingDoc,setUploadingDoc]=useState(false);useEffect(()=>{loadProfile()},[]);const loadProfile=async()=>{try{const data=await api('/profile');setProfile(data);setFormData({date_of_birth:data.date_of_birth||'',national_id:data.national_id||'',gender:data.gender||'',county:data.county||'',sub_county:data.sub_county||'',constituency:data.constituency||'',address:data.address||'',guardian_name:data.guardian_name||'',guardian_phone:data.guardian_phone||'',guardian_relationship:data.guardian_relationship||'',institution:data.institution||'',student_number:data.student_number||'',course:data.course||'',year_of_study:data.year_of_study||'',admission_year:data.admission_year||'',monthly_household_income:data.monthly_household_income||'',household_size:data.household_size||1})}catch(e){console.error(e)}};const handleUpdate=async(e)=>{e.preventDefault();await run(async()=>{await api('/profile',{method:'PATCH',body:formData});await loadProfile();setEditMode(false);setNotice('Profile updated successfully')})};const handleDocUpload=async(docType,e)=>{const file=e.target.files?.[0];if(!file)return;setUploadingDoc(true);try{const fd=new FormData();fd.append('document_type',docType);fd.append('file',file);await api('/profile/documents',{method:'POST',body:fd});await loadProfile();setNotice(`${docType} uploaded successfully`)}catch(err){alert(err.message)}finally{setUploadingDoc(false);e.target.value=''}};const handleDocDelete=async(docId)=>{if(!confirm('Delete this document?'))return;await run(async()=>{await api(`/profile/documents/${docId}`,{method:'DELETE'});await loadProfile();setNotice('Document deleted')})};if(!profile)return <div className="panel"><p>Loading profile...</p></div>;const profileComplete=profile.profile_complete;return <><PageHeading eyebrow="MY PROFILE" title="Profile & Documents" desc="Complete your profile to apply for bursaries. All required fields must be filled." action={!profileComplete&&<Badge tone="warning">Incomplete</Badge>}/>{!profileComplete&&<Notice type="error">Your profile is incomplete. Please fill all required fields and upload necessary documents before applying for bursaries.</Notice>}<div className="profile-layout"><div className="profile-main"><section className="panel"><div className="panel-head"><div><h3>Personal Information</h3><p>Your basic details and contact information</p></div>{!editMode&&<Button kind="outline" size="small" onClick={()=>setEditMode(true)}>Edit Profile</Button>}</div>{!editMode?<div className="info-grid"><Info label="Full Name" value={user.full_name}/><Info label="Email" value={user.email}/><Info label="Phone" value={user.phone||'Not provided'}/><Info label="Date of Birth" value={profile.date_of_birth||'Not provided'}/><Info label="National ID" value={profile.national_id||'Not provided'}/><Info label="Gender" value={profile.gender||'Not provided'}/><Info label="County" value={profile.county||'Not provided'}/><Info label="Constituency" value={profile.constituency||'Not provided'}/><Info label="Sub-County" value={profile.sub_county||'Not provided'}/><Info label="Address" value={profile.address||'Not provided'}/><Info label="Guardian Name" value={profile.guardian_name||'Not provided'}/><Info label="Guardian Phone" value={profile.guardian_phone||'Not provided'}/><Info label="Guardian Relationship" value={profile.guardian_relationship||'Not provided'}/></div>:<form onSubmit={handleUpdate}><div className="form-grid"><Field label="Date of Birth *"><input type="date" value={formData.date_of_birth} onChange={e=>setFormData({...formData,date_of_birth:e.target.value})} required/></Field><Field label="National ID *"><input value={formData.national_id} onChange={e=>setFormData({...formData,national_id:e.target.value})} required placeholder="12345678"/></Field><Field label="Gender *"><select value={formData.gender} onChange={e=>setFormData({...formData,gender:e.target.value})} required><option value="">Select gender</option><option>Male</option><option>Female</option><option>Other</option><option>Prefer not to say</option></select></Field><Field label="County *"><input value={formData.county} onChange={e=>setFormData({...formData,county:e.target.value})} required placeholder="e.g. Nairobi"/></Field><Field label="Constituency *"><input value={formData.constituency} onChange={e=>setFormData({...formData,constituency:e.target.value})} required placeholder="e.g. Webuye East"/></Field><Field label="Sub-County"><input value={formData.sub_county} onChange={e=>setFormData({...formData,sub_county:e.target.value})} placeholder="e.g. Westlands"/></Field><Field label="Address"><input value={formData.address} onChange={e=>setFormData({...formData,address:e.target.value})} placeholder="Postal or physical address"/></Field><Field label="Guardian Name"><input value={formData.guardian_name} onChange={e=>setFormData({...formData,guardian_name:e.target.value})} placeholder="Parent or guardian"/></Field><Field label="Guardian Phone"><input value={formData.guardian_phone} onChange={e=>setFormData({...formData,guardian_phone:e.target.value})} placeholder="07xx xxx xxx"/></Field><Field label="Guardian Relationship"><input value={formData.guardian_relationship} onChange={e=>setFormData({...formData,guardian_relationship:e.target.value})} placeholder="e.g. Mother, Father, Uncle"/></Field></div><div className="form-actions"><Button type="submit" disabled={busy}>{busy?'Saving...':'Save Changes'}</Button><Button kind="ghost" type="button" onClick={()=>setEditMode(false)}>Cancel</Button></div></form>}</section><section className="panel"><div className="panel-head"><div><h3>Educational Details</h3><p>Your current institution and course information</p></div>{!editMode&&<Button kind="outline" size="small" onClick={()=>setEditMode(true)}>Edit Profile</Button>}</div>{!editMode?<div className="info-grid"><Info label="Institution" value={profile.institution||'Not provided'}/><Info label="Student Number" value={profile.student_number||'Not provided'}/><Info label="Course/Program" value={profile.course||'Not provided'}/><Info label="Year of Study" value={profile.year_of_study||'Not provided'}/><Info label="Admission Year" value={profile.admission_year||'Not provided'}/></div>:<form onSubmit={handleUpdate}><div className="form-grid"><Field label="Institution *"><input value={formData.institution} onChange={e=>setFormData({...formData,institution:e.target.value})} required placeholder="University, college or school"/></Field><Field label="Student Number *"><input value={formData.student_number} onChange={e=>setFormData({...formData,student_number:e.target.value})} required placeholder="Your registration number"/></Field><Field label="Course/Program *"><input value={formData.course} onChange={e=>setFormData({...formData,course:e.target.value})} required placeholder="e.g. Computer Science"/></Field><Field label="Year of Study *"><select value={formData.year_of_study} onChange={e=>setFormData({...formData,year_of_study:e.target.value})} required><option value="">Select year</option>{['Year 1','Year 2','Year 3','Year 4','Year 5','Secondary school','TVET'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Admission Year"><input type="number" value={formData.admission_year} onChange={e=>setFormData({...formData,admission_year:e.target.value})} placeholder="e.g. 2024" min="2000" max={new Date().getFullYear()}/></Field></div><div className="form-actions"><Button type="submit" disabled={busy}>{busy?'Saving...':'Save Changes'}</Button><Button kind="ghost" type="button" onClick={()=>setEditMode(false)}>Cancel</Button></div></form>}</section><section className="panel"><div className="panel-head"><div><h3>Financial Information</h3><p>Household income details for bursary assessment</p></div>{!editMode&&<Button kind="outline" size="small" onClick={()=>setEditMode(true)}>Edit Profile</Button>}</div>{!editMode?<div className="info-grid"><Info label="Monthly Household Income" value={money(profile.monthly_household_income)}/><Info label="Household Size" value={`${profile.household_size} people`}/></div>:<form onSubmit={handleUpdate}><div className="form-grid"><Field label="Monthly Household Income (KES) *"><input type="number" value={formData.monthly_household_income} onChange={e=>setFormData({...formData,monthly_household_income:Number(e.target.value)})} required min="0" placeholder="0"/></Field><Field label="People in Household *"><input type="number" value={formData.household_size} onChange={e=>setFormData({...formData,household_size:Number(e.target.value)})} required min="1" max="50"/></Field></div><div className="form-actions"><Button type="submit" disabled={busy}>{busy?'Saving...':'Save Changes'}</Button><Button kind="ghost" type="button" onClick={()=>setEditMode(false)}>Cancel</Button></div></form>}</section></div><aside className="profile-aside"><section className="panel"><div className="panel-head"><div><h3>Required Documents</h3><p>Upload to complete your profile</p></div></div><div className="profile-docs-list">{[{type:'National ID',required:true,uploaded:profile.has_national_id_doc},{type:'Student ID',required:true,uploaded:profile.has_student_id_doc},{type:'Admission Letter',required:false,uploaded:profile.has_admission_letter}].map(({type,required,uploaded})=><div className="profile-doc-item" key={type}><div className="profile-doc-info"><b>{type} {required&&<span className="req-badge">Required</span>}</b><small>{uploaded?'Uploaded':'Not uploaded'}</small></div><div className="profile-doc-actions">{uploaded?<>{profile.profile_documents.filter(d=>d.document_type===type).map(doc=><div key={doc.id} className="uploaded-doc-item"><button className="icon-btn" title="Download" onClick={async()=>{try{const blob=await api(`/profile/documents/${doc.id}/download`);const url=URL.createObjectURL(blob);const el=document.createElement('a');el.href=url;el.download=doc.original_filename;el.click();URL.revokeObjectURL(url)}catch(e){alert(e.message)}}}><ArrowDownToLine size={15}/></button><button className="icon-btn" title="Delete" onClick={()=>handleDocDelete(doc.id)}><X size={15}/></button></div>)}</>:<label className="upload-doc-btn" title={`Upload ${type}`}><UploadCloud size={16}/> Upload<input type="file" accept=".pdf,.jpg,.jpeg,.png" disabled={uploadingDoc} onChange={e=>handleDocUpload(type,e)}/></label>}</div></div>)}</div>{profile.profile_documents.filter(d=>!['National ID','Student ID','Admission Letter'].includes(d.document_type)).length>0&&<><hr/><h4>Other Documents</h4>{profile.profile_documents.filter(d=>!['National ID','Student ID','Admission Letter'].includes(d.document_type)).map(doc=><div className="document-row" key={doc.id}><div className="doc-icon"><FileText size={18}/></div><div className="document-info"><b>{doc.document_type}</b><small>{doc.original_filename}</small></div><button className="icon-btn" onClick={()=>handleDocDelete(doc.id)}><X size={16}/></button></div>)}</>}</section><section className="panel profile-status-card"><div className="profile-status-icon" style={{background:profileComplete?'var(--green-soft)':'#fcefc7',color:profileComplete?'var(--green)':'#805700'}}>{profileComplete?<CheckCircle2 size={24}/>:<AlertTriangle size={24}/>}</div><h3>{profileComplete?'Profile Complete':'Profile Incomplete'}</h3><p>{profileComplete?'Your profile is complete. You can now apply for bursaries.':'Complete all required fields and upload necessary documents to apply for bursaries.'}</p>{!profileComplete&&<div className="profile-checklist"><small>Required:</small><ul>{[{label:'Personal details',done:!!(profile.date_of_birth&&profile.national_id&&profile.gender&&profile.county&&profile.constituency)},{label:'Educational details',done:!!(profile.institution&&profile.student_number&&profile.course&&profile.year_of_study)},{label:'Financial information',done:profile.monthly_household_income>0&&profile.household_size>0},{label:'National ID document',done:profile.has_national_id_doc},{label:'Student ID document',done:profile.has_student_id_doc}].map((item,i)=><li key={i} style={{color:item.done?'var(--green)':'var(--mute)'}}>{item.done?<CheckCircle2 size={14}/>:<Clock3 size={14}/>} {item.label}</li>)}</ul></div>}</section></aside></div></>}


function StaffPage({run,refresh,busy}){const [staff,setStaff]=useState([]);const [showCreate,setShowCreate]=useState(false);const [constituencies,setConstituencies]=useState([]);useEffect(()=>{loadStaff();loadConstituencies()},[]);const loadStaff=async()=>{try{const data=await api('/staff');setStaff(data)}catch(e){console.error(e)}};const loadConstituencies=async()=>{try{const data=await api('/bursaries/constituencies');setConstituencies(data)}catch(e){console.error(e)}};async function createStaff(e){e.preventDefault();const fd=new FormData(e.currentTarget);await run(async()=>{await api('/staff',{method:'POST',body:{full_name:fd.get('full_name'),email:fd.get('email'),password:fd.get('password'),role:fd.get('role'),constituency:fd.get('constituency')||''}});setShowCreate(false);await loadStaff();await refresh();})}return <><PageHeading eyebrow="TEAM MANAGEMENT" title="Staff accounts" desc="Manage admin and reviewer accounts with constituency assignments." action={<Button onClick={()=>setShowCreate(!showCreate)}><Plus size={17}/> Add staff member</Button>}/>{showCreate&&<form className="panel create-form" onSubmit={createStaff}><h3>New staff account</h3><div className="form-grid"><Field label="Full name"><input name="full_name" required minLength="2"/></Field><Field label="Email address"><input name="email" type="email" required/></Field><Field label="Password"><input name="password" type="password" required minLength="12" placeholder="At least 12 characters"/></Field><Field label="Role"><select name="role" required><option value="">Select role</option><option value="admin">Administrator</option><option value="reviewer">Reviewer</option></select></Field><Field label="Constituency (for reviewers)"><select name="constituency"><option value="">No constituency (admin only)</option>{constituencies.map(c=><option key={c.constituency} value={c.constituency}>{c.constituency}</option>)}</select></Field></div><div className="form-actions"><Button type="submit" disabled={busy}>{busy?'Creating…':'Create account'}</Button><Button kind="ghost" type="button" onClick={()=>setShowCreate(false)}>Cancel</Button></div></form>}<div className="panel table-panel">{staff.length===0?<Empty title="No staff accounts" desc="Create admin and reviewer accounts to manage applications."/>:<div className="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Constituency</th></tr></thead><tbody>{staff.map(s=><tr key={s.id}><td><b>{s.full_name}</b></td><td>{s.email}</td><td><Badge tone={s.role==='admin'?'info':'success'}>{s.role==='admin'?'Administrator':'Reviewer'}</Badge></td><td>{s.constituency?<div className="constituency-badge"><MapPin size={12}/> {s.constituency}</div>:'—'}</td></tr>)}</tbody></table></div>}</div></>}
